"""audio.py: every sound is generated by code (no audio files). If there is no sound device the game still runs."""
import array
import math
import random
import pygame


class Audio:
    def __init__(self):
        self.ok = False
        self.sounds = {}
        self.enabled = True
        try:
            pygame.mixer.pre_init(22050, -16, 2, 512)
            pygame.mixer.init()
            self.rate, _, self.ch = pygame.mixer.get_init()
            self.ok = True
            self._build()
        except Exception:
            self.ok = False

    def _snd(self, samples):
        a = array.array("h")
        for v in samples:
            iv = int(max(-1.0, min(1.0, v)) * 32767)
            a.append(iv)
            if self.ch == 2:
                a.append(iv)
        return pygame.mixer.Sound(buffer=a.tobytes())

    def _build(self):
        R, rnd = self.rate, random.Random(2)
        n = lambda sec: int(R * sec)
        # heartbeat: two soft low thumps
        hb = [0.0] * n(0.55)
        for start, amp in ((0.0, 1.0), (0.2, 0.7)):
            for i in range(n(0.18)):
                t = i / R
                k = start and 1 or 1
                hb[i + n(start)] += amp * math.sin(2 * math.pi * (62 - 120 * t) * t) * math.exp(-t * 20)
        self.sounds["heart"] = self._snd([v * 0.9 for v in hb])
        # lantern found: a soft bell
        self.sounds["pickup"] = self._snd([(math.sin(2 * math.pi * 880 * i / R) * 0.5 + math.sin(2 * math.pi * 1318 * i / R) * 0.3 + math.sin(2 * math.pi * 1760 * i / R) * 0.15) * math.exp(-i / R * 4) * 0.5 for i in range(n(1.0))])
        # shadow hit: low rumble with a noise burst
        self.sounds["hit"] = self._snd([(math.sin(2 * math.pi * (90 - 60 * (i / R)) * i / R) * 0.8 + rnd.uniform(-1, 1) * 0.5 * math.exp(-i / R * 18)) * math.exp(-i / R * 5) for i in range(n(0.7))])
        # footsteps: two soft crunches
        for name, f in (("step1", 0.55), ("step2", 0.42)):
            lp, out = 0.0, []
            for i in range(n(0.1)):
                lp += (rnd.uniform(-1, 1) - lp) * f
                out.append(lp * math.exp(-i / R * 38) * 0.6)
            self.sounds[name] = self._snd(out)
        # out of breath
        lp, out = 0.0, []
        for i in range(n(0.6)):
            t = i / R
            lp += (rnd.uniform(-1, 1) - lp) * 0.2
            out.append(lp * math.sin(math.pi * t / 0.6) * 0.5)
        self.sounds["gasp"] = self._snd(out)
        # wind: slow noise that swells (loops)
        L = n(4.0)
        raw = [rnd.uniform(-1, 1) for _ in range(L)]
        sm, acc = [], 0.0
        for i in range(L):
            acc += (raw[i] - acc) * 0.02
            sm.append(acc * (0.6 + 0.4 * math.sin(2 * math.pi * i / L)) * 4.0)
        self.sounds["wind"] = self._snd(sm)
        # whispers: breathy, wavering noise (loops), used for the "shadow near" cue
        L = n(3.0)
        lp1 = lp2 = 0.0
        wh = []
        for i in range(L):
            lp1 += (rnd.uniform(-1, 1) - lp1) * 0.35
            lp2 += (lp1 - lp2) * 0.35
            t = i / R
            wh.append((lp1 - lp2) * 5.0 * (0.5 + 0.5 * math.sin(2 * math.pi * 4.3 * t)) * (0.6 + 0.4 * math.sin(2 * math.pi * 0.67 * t)))
        self.sounds["whisper"] = self._snd(wh)
        # a different bell for each lantern (pentatonic, rising), and a bright chord when the last is found
        for k, f0 in enumerate((523.25, 587.33, 659.25, 783.99, 880.0, 1046.5), 1):
            self.sounds["chime%d" % k] = self._snd([(math.sin(2 * math.pi * f0 * i / R) * 0.5 + math.sin(2 * math.pi * f0 * 2.01 * i / R) * 0.25 + math.sin(2 * math.pi * f0 * 3.0 * i / R) * 0.1) * math.exp(-i / R * 3.2) * 0.5 for i in range(n(1.4))])
        fin = [0.0] * n(2.6)
        for j, f0 in enumerate((523.25, 659.25, 783.99, 1046.5)):
            for i in range(n(2.0)):
                fin[i + n(0.18 * j)] += math.sin(2 * math.pi * f0 * i / R) * math.exp(-i / R * 1.8) * 0.22
        self.sounds["finale"] = self._snd(fin)
        # ambience: an owl, a creaking branch, a distant snap
        owl = []
        for i in range(n(1.3)):
            t = i / R
            env = (math.exp(-((t - 0.25) / 0.12) ** 2) + 0.8 * math.exp(-((t - 0.7) / 0.18) ** 2))
            owl.append(math.sin(2 * math.pi * (330 - 45 * t) * t + 3 * math.sin(2 * math.pi * 5 * t)) * env * 0.5)
        self.sounds["owl"] = self._snd(owl)
        lp, creak = 0.0, []
        for i in range(n(1.1)):
            t = i / R
            lp += (rnd.uniform(-1, 1) - lp) * 0.08
            creak.append((lp * 3.0 * (0.5 + 0.5 * math.sin(2 * math.pi * (14 + 10 * t) * t))) * math.sin(math.pi * t / 1.1) * 0.5)
        self.sounds["creak"] = self._snd(creak)
        self.sounds["snap"] = self._snd([rnd.uniform(-1, 1) * math.exp(-i / R * 45) * 0.5 for i in range(n(0.25))])
        self._amb_t = 8.0
        self._wind = None
        self._whisper = None

    def start_ambience(self):
        if self.ok and self._wind is None:
            self._wind = self.sounds["wind"].play(-1)
            if self._wind:
                self._wind.set_volume(0.18)

    def whisper(self, level, pan=0.0):
        """level 0..1: how loud the whispers are (0 stops them)."""
        if not (self.ok and self.enabled):
            return
        if self._whisper is None:
            if level <= 0.01:
                return
            self._whisper = self.sounds["whisper"].play(-1)
        if self._whisper:
            self._whisper.set_volume(level * (1 - max(0.0, pan)), level * (1 + min(0.0, pan)))

    def ambient(self, dt):
        """Occasional distant sounds (an owl, a creaking branch, a snap) from a random side."""
        self._amb_t -= dt
        if self._amb_t <= 0:
            self._amb_t = random.uniform(7.0, 16.0)
            self.play(random.choice(("owl", "creak", "snap", "owl")), random.uniform(0.12, 0.3), random.uniform(-1, 1))

    def play(self, name, volume=1.0, pan=0.0):
        """pan: -1 = left ear ... +1 = right ear."""
        if not (self.ok and self.enabled) or name not in self.sounds:
            return
        ch = self.sounds[name].play()
        if ch:
            ch.set_volume(volume * (1 - max(0.0, pan)), volume * (1 + min(0.0, pan)))

    def toggle(self):
        self.enabled = not self.enabled
        if self._wind:
            self._wind.set_volume(0.18 if self.enabled else 0.0)
